<script setup lang="ts">
import {useVehicleStore} from '../stores/vehicle';import {windowConfig,type WindowId} from '../config/v8-windows';
const store=useVehicleStore();const labels={moving:'正在执行',done:'已完成',replaced:'已被替换',paused:'已暂停'};
const sourceNames:Record<string,string>={voice:'语音',text:'文字',button:'按钮',slider:'滑块',playback:'演示'};
</script>
<template><section><h2>最近操作</h2><p v-if="!store.history.length">试着说“副驾车窗开一半”</p><div class="history-list"><article class="history-item" v-for="entry in store.history" :key="entry.id"><small>{{sourceNames[entry.source]}} · {{new Date(entry.started).toLocaleTimeString()}}</small><p>{{entry.text}}</p><div class="history-target" v-for="(target,id) in entry.targets" :key="id">{{windowConfig[id as WindowId].label}} · {{Math.round(target!.value*100)}}% · {{labels[target!.status]}}</div><p v-if="!Object.keys(entry.targets).length">{{entry.message}}</p><details><summary>操作详情</summary><p>指令 {{entry.id}}</p><p v-if="entry.commandIds && entry.commandIds.length>1">连续调节 {{entry.commandIds.length}} 次</p><template v-if="entry.source==='voice'||entry.source==='text'"><p>{{entry.route}}<span v-if="entry.model"> · {{entry.model}}</span></p><p v-if="entry.elapsedMs!==undefined">理解耗时 {{entry.elapsedMs}} ms</p></template><p v-for="(target,id) in entry.targets" :key="id">{{windowConfig[id as WindowId].label}}：{{target!.ended?((target!.ended-entry.started)/1000).toFixed(1)+' 秒':'—'}}</p></details></article></div></section></template>
